use super::schema::profile;
use super::*;
use crate::FileSetRequest;
use arrow_array::{Array, LargeBinaryArray, LargeStringArray, StructArray};
use futures::TryStreamExt;
use open_arrow_access_core::{Accessor, ReadOptions, ScanPlanner};
use open_arrow_access_storage::OpenDalAccessor;
use open_arrow_access_test_support::temp_fs;
use serde_json::{Value, json};

const ITEM: &str = "ocr/item-000001/item-000001-00000003-0002.txt";
const PART: &str = "ocr/part-000008/part-000008-00000003-0001.txt";

// Generated by the Python disk-index/export path; consumed by native Arrow tests.
fn fixture() -> Value {
    serde_json::from_slice(include_bytes!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../testdata/bhl/pages/metadata.json"
    )))
    .unwrap()
}

fn metadata(value: &Value) -> BhlMetadata {
    BhlMetadata::from_json(&serde_json::to_vec(value).unwrap()).unwrap()
}

#[test]
fn complete_join_preserves_all_fields_rights_relation_order_and_doi_types() {
    assert_eq!(profile().len(), 13);
    assert_eq!(
        profile().iter().map(|p| p.columns.len()).sum::<usize>(),
        104
    );
    let source = metadata(&fixture());
    let part = source.join(PART).unwrap();
    assert!(part.report.missing.is_empty());
    assert!(part.report.conflicts.is_empty());
    assert_eq!(
        part.tables["creatoridentifier"]
            .iter()
            .map(|r| r["CreatorID"].as_str())
            .collect::<Vec<_>>(),
        ["4", "2", "4"]
    );
    assert_eq!(part.tables["doi"].len(), 4);
    assert_eq!(
        part.tables["item"][0]["RightsStatement"],
        "\"Original rights\""
    );
    assert_eq!(part.tables["item"][0]["ItemID"], "01");
    assert_eq!(part.tables["part"][0]["RightsStatement"], "Part rights");
    assert_eq!(part.identity.sequence, 1);
    let item = source.join(ITEM).unwrap();
    assert!(item.tables["part"].is_empty());
    assert!(item.tables["partpage"].is_empty());
    assert_eq!(item.tables["creatoridentifier"].len(), 1);
    assert_eq!(item.tables["doi"].len(), 3);
}

#[test]
fn missing_joins_and_conflicts_are_reported_and_single_duplicates_rejected() {
    let mut value = fixture();
    value["tables"]["part"][0]["ItemID"] = json!("7");
    value["tables"]["partpage"][0]["SequenceOrder"] = json!("4");
    let source = metadata(&value);
    let report = source.report(PART).unwrap();
    assert_eq!(report.conflicts, ["item-parent", "page-sequence"]);
    assert!(report.missing.contains(&"item".into()));
    let mut value = fixture();
    value["tables"]["page"] = json!([]);
    assert!(
        metadata(&value)
            .report(ITEM)
            .unwrap()
            .missing
            .contains(&"page".into())
    );
    let row = value["tables"]["item"][0].clone();
    value["tables"]["item"].as_array_mut().unwrap().push(row);
    value["source_tables"]["item"]["rows"] = json!(2);
    assert!(BhlMetadata::from_json(&serde_json::to_vec(&value).unwrap()).is_err());
    let mut value = fixture();
    value["tables"].as_object_mut().unwrap().remove("doi");
    assert!(BhlMetadata::from_json(&serde_json::to_vec(&value).unwrap()).is_err());
}

#[tokio::test]
async fn native_partitions_write_binary_nested_arrow_projection_and_missing_joins() {
    let (_root, operator) = temp_fs(&[(ITEM, b"\r\n\xff"), (PART, b"")]);
    let source = BhlPageAccessor::new(OpenDalAccessor::new(operator), metadata(&fixture()));
    let plan = source
        .plan_scan(FileSetRequest::new([ITEM, PART]))
        .await
        .unwrap();
    let partitions = plan.partitions.try_collect::<Vec<_>>().await.unwrap();
    assert_eq!(partitions.len(), 2);
    for (index, partition) in partitions.into_iter().enumerate() {
        let mut reader = partition.await.unwrap();
        let batch = reader.next().await.unwrap().unwrap();
        assert_eq!(batch.num_rows(), 1);
        let data = batch
            .column_by_name("data")
            .unwrap()
            .as_any()
            .downcast_ref::<LargeBinaryArray>()
            .unwrap();
        assert_eq!(
            data.value(0),
            if index == 0 {
                b"\r\n\xff".as_slice()
            } else {
                b"".as_slice()
            }
        );
        let nested = batch
            .column_by_name("metadata")
            .unwrap()
            .as_any()
            .downcast_ref::<StructArray>()
            .unwrap();
        let item = nested
            .column_by_name("item")
            .unwrap()
            .as_any()
            .downcast_ref::<StructArray>()
            .unwrap();
        let rights = item
            .column_by_name("RightsStatement")
            .unwrap()
            .as_any()
            .downcast_ref::<LargeStringArray>()
            .unwrap();
        assert_eq!(rights.value(0), "\"Original rights\"");
        assert!(
            batch
                .column_by_name("source_entry_index")
                .unwrap()
                .is_null(0)
        );
        assert!(reader.next().await.unwrap().is_none());
    }
    let options = ReadOptions::default().with_projection(["metadata", "page_id"]);
    let mut projected = source
        .open(FileSetRequest::new([ITEM]).with_options(options))
        .await
        .unwrap();
    assert_eq!(projected.next().await.unwrap().unwrap().num_columns(), 2);
    assert!(
        source
            .plan_scan(FileSetRequest::new(["ocr/item-1/item-1-4-1.txt"]))
            .await
            .is_err()
    );
}

#[test]
fn empty_foreign_key_cells_remain_lexical_and_do_not_become_zero_ids() {
    let mut value = fixture();
    value["tables"]["item"][0]["TitleID"] = json!("");
    value["tables"]["partcreator"][0]["CreatorID"] = json!("");
    let source = metadata(&value);
    let joined = source.join(PART).unwrap();
    assert!(joined.report.missing.contains(&"title".into()));
    assert!(joined.tables["creator"].is_empty());
    assert!(joined.tables["creatoridentifier"].is_empty());
    assert_eq!(joined.tables["partcreator"][0]["CreatorID"], "");
}

#[test]
fn rejects_bad_identity_and_keeps_numeric_padding() {
    assert_eq!(BhlPageIdentity::parse(ITEM).unwrap().page_id, 3);
    for key in [
        "ocr/item-1/part-1-3-1.txt",
        "ocr/item-1/item-2-3-1.txt",
        "ocr/item-1/item-1-0-1.txt",
        "ocr/item-1/item-1-3-18446744073709551616.txt",
    ] {
        assert!(BhlPageIdentity::parse(key).is_err());
    }
}
